actionJson:
{
  "id": "20spo-page-001-set-home",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "web-set-welcome-page",
  "operationDefinition": {
    "type": "OpenApiConnection",
    "inputs": {
      "host": {
        "connectionName": "shared_sharepointonline",
        "operationId": "HttpRequest",
        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
      },
      "parameters": {
        "dataset": "{{SITE_URL}}",
        "parameters/method": "POST",
        "parameters/uri": "_api/web",
        "parameters/headers": {
          "Accept": "application/json;odata=nometadata",
          "Content-Type": "application/json;charset=utf-8",
          "X-HTTP-Method": "MERGE",
          "IF-MATCH": "*"
        },
        "parameters/body": "{\"WelcomePage\":\"{{WELCOME_PAGE}}\"}"
      },
      "authentication": {
        "type": "Raw",
        "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
      }
    },
    "runAfter": {},
    "description": "Sets the welcome page for the SharePoint web. Provide WELCOME_PAGE as a site-relative path, for example SitePages/Home.aspx.",
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0064-4000-0000-000000000001"
    }
  }
}

{
  "id": "20spo-page-002-update",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "page-update-properties",
  "operationDefinition": {
    "type": "OpenApiConnection",
    "inputs": {
      "host": {
        "connectionName": "shared_sharepointonline",
        "operationId": "HttpRequest",
        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
      },
      "parameters": {
        "dataset": "{{SITE_URL}}",
        "parameters/method": "POST",
        "parameters/uri": "_api/web/GetList('@{replace(concat(uriPath('{{SITE_URL}}'), '/'), '//', '/')}SitePages')/items({{PAGE_ID}})",
        "parameters/headers": {
          "Accept": "application/json;odata=nometadata",
          "Content-Type": "application/json;charset=utf-8",
          "X-HTTP-Method": "MERGE",
          "IF-MATCH": "*"
        },
        "parameters/body": "{{PAGE_BODY}}"
      },
      "authentication": {
        "type": "Raw",
        "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
      }
    },
    "runAfter": {},
    "description": "Updates properties of a modern page in the Site Pages library (found by URL, so it works on non-English sites). Provide PAGE_BODY as a JSON object, for example {\"Title\":\"New title\",\"Description\":\"New description\"}.",
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0064-4000-0000-000000000002"
    }
  }
}
